async enroll(subject: string, customer?: ReadCustomerResponseData): Promise<void> {
    await this.registerBillingSchedule(subject);
    if (this.billingCycle === ValidBillingCycles.topUp) {
        // Top up offerings prepay the customer wallet on enrollment
        await this.topUp({ customer });
        return;
    }
    const upfrontPaidDimensions = this.dimensions.filter(
        (dimension) => dimension?.paymentSchedule === PaymentSchedule.upfront,
    );
    if (upfrontPaidDimensions?.length && this.usageOverrides?.length) {
        const currentDimensions = JSON.parse(JSON.stringify(this.dimensions));
        this.dimensions = upfrontPaidDimensions;
        this.isEnrollment = true;
        await this.processBilling(undefined, undefined, customer);
        this.dimensions = currentDimensions;
    }
}

/**
 * Refills the customer wallet whenever the balance has dropped below `topUpThreshold * topUpAmount`.
 * The wallet is always refilled back up to the `topUpAmount` by creating an invoice whose payment is stored as credit.
 * A balance which is exactly at the threshold is considered sufficient, and therefore is not topped up.
 */
async topUp({ customer }: { customer: ReadCustomerResponseData }): Promise<string | void> {
    const topUpAmount = parseFloat(this.topUpAmount ? this.topUpAmount : '0');
    if (!topUpAmount) {
        UsageBased.logger.warn(
            `No top up amount found for offering: ${this.offeringName}. Skipping the top up for customer: ${this.customerId}`,
        );
        return;
    }
    const balance = await this.getCurrentCreditBalance(customer);
    const thresholdAmount = this.getTopUpThresholdAmount();
    UsageBased.logger.log(
        `Evaluating top up for customer: ${this.customerId}, balance: ${balance}, threshold: ${thresholdAmount}, top up amount: ${topUpAmount}`,
    );
    if (balance >= thresholdAmount) {
        // The wallet still holds enough credit, nothing to do.
        return;
    }
    const amountDue = parseFloat((topUpAmount - balance).toFixed(2));
    const lineItems = new InvoiceLineItems();
    lineItems.addLineItem(new InvoiceLineItem(`${this.offeringName} - Top Up`, 1, amountDue));
    const { invoiceId } = await this.invoicesService.create({
        businessID: this.businessID,
        customer,
        customerId: this.customerId,
        items: lineItems,
        invoiceDate: new Date().toISOString(),
        currency: Offering.getCurrency({ customer, offering: this }),
        storePaymentAsCredit: true,
    });
    return invoiceId;
}

/**
 * The hourly processing of a top up offering.
 * Any usage which occurred within the given time range is deducted from the customer wallet,
 * even when the usage exceeds the current balance of the wallet. No usage invoice is created.
 * Once the usage is deducted, the wallet is evaluated for a top up with the updated balance.
 */
async processTopUp({
    customer,
    startDate,
    endDate,
    creditService,
}: {
    customer?: ReadCustomerResponseData;
    startDate?: Date;
    endDate?: Date;
    creditService?: CreditService;
}): Promise<string | void> {
    const { startTime, endTime } = Billing.billingCycleToTimeRange(ValidBillingCycles.topUp);
    const usageStartDate = startDate ? startDate : new Date(startTime);
    const usageEndDate = endDate ? endDate : new Date(endTime);
    const setCreditService = creditService ? creditService : this.creditService;
    const lineItems = await Offering.getLineItemsForUsage({
        startDate: usageStartDate,
        endDate: usageEndDate,
        customer,
        lineItems: new InvoiceLineItems(),
        negative: false,
        businessID: this.businessID,
        customerId: this.customerId,
        customerService: this.customerService,
        offeringInstance: this,
        dimensions: this.dimensions,
    });
    const usageTotal = parseFloat(lineItems.getTotal().toFixed(2));
    const balance = await this.getCurrentCreditBalance(customer);
    UsageBased.logger.log(
        `Processing top up usage for customer: ${this.customerId} between ${usageStartDate.toISOString()} and ${usageEndDate.toISOString()}. Usage total: ${usageTotal}, balance: ${balance}`,
    );
    if (usageTotal) {
        if (!setCreditService) {
            UsageBased.logger.error(
                `No credit service found for offering: ${this.offeringName}. Unable to deduct usage from the customer wallet for customer: ${this.customerId}`,
            );
        } else {
            await setCreditService.create({
                businessID: this.businessID,
                customerId: this.customerId,
                timestamp: new Date().toISOString(),
                transactionAmount: (usageTotal * -1).toFixed(2),
                metadata: {
                    reason: `Usage for ${this.offeringName}`,
                    offeringId: this.offeringId,
                },
            });
        }
    }
    // The balance is updated in memory so the top up is evaluated against the balance after the usage deduction
    const updatedBalance = parseFloat((balance - usageTotal).toFixed(2));
    if (customer) {
        customer.creditBalance = updatedBalance.toString();
    }
    return this.topUp({ customer });
}

