import { IsNotEmpty, IsString } from 'class-validator';

export class OfferingTopUpCheckerDto {
    /**
     * The unique identifier of the offering which is checked for top ups
     * @example "e345f409-daca-4144-91d2-0a0f87c96581"
     */
    @IsString()
    @IsNotEmpty()
    public offeringId: string;

    /**
     * The unique identifier for the SaaS business
     * @example myCoolCorp
     */
    @IsString()
    @IsNotEmpty()
    public businessID: string;
}

import { Inject, Injectable, Logger, forwardRef } from '@nestjs/common';
import { serializeError } from 'serialize-error';
import { AuditService } from '../../audit/audit.service.js';
import { AuditScope } from '../../audit/entities/audit.interface.js';
import { ContractService } from '../../contract/contract.service.js';
import { CreditService } from '../../credit/credit.service.js';
import { CustomerService } from '../../customer/customer.service.js';
import { ReadCustomerResponseData } from '../../customer/entities/customer.entity.js';
import { ValidBillingCycles } from '../../offering/dto/createOffering.dto.js';
import { Offering, UsageBased } from '../../offering/entities/offeringPackage.entity.js';
import { OfferingTopUpCheckerDto } from './dto/offeringTopUpChecker.dto.js';

/**
 * Runs on an hourly basis for every offering which uses the `topUp` billing cycle.
 * Every customer enrolled in the offering has their usage of the last hour deducted from their wallet,
 * and their wallet refilled whenever the balance drops below the top up threshold.
 */
@Injectable()
export class OfferingTopUpChecker {
    private static readonly logger = new Logger(OfferingTopUpChecker.name);

    constructor(
        @Inject(forwardRef(() => CustomerService)) readonly customerService: CustomerService,
        @Inject(forwardRef(() => ContractService)) readonly contractService: ContractService,
        @Inject(forwardRef(() => CreditService)) readonly creditService: CreditService,
    ) {}

    /**
     * Evaluates every customer enrolled in the given top up offering.
     */
    async checkOfferingTopUp({ businessID, offeringId }: OfferingTopUpCheckerDto): Promise<void> {
        OfferingTopUpChecker.logger.log(
            `Starting the top up check for offering: ${offeringId} in business: ${businessID}`,
        );
        let customers: ReadCustomerResponseData[] = [];
        try {
            const { data } = await this.customerService.findAllCustomersWithOfferingId({ businessID, offeringId });
            customers = data ? data : [];
        } catch (error) {
            OfferingTopUpChecker.logger.error(
                `Failed to find customers for offering: ${offeringId}`,
                serializeError(error),
            );
            return;
        }
        for (const customer of customers) {
            try {
                await this.checkCustomerTopUp({ businessID, offeringId, customer });
            } catch (error) {
                AuditService.publishEvent({
                    message: 'Failed to process the top up for a customer',
                    topic: AuditScope.ERROR,
                    data: [
                        {
                            error: serializeError(error),
                            businessID,
                            offeringId,
                            customerId: customer?.customerId,
                        },
                    ],
                });
            }
        }
    }

    /**
     * Deducts the usage of the last hour from the customer wallet and evaluates the top up with the updated balance.
     */
    async checkCustomerTopUp({
        businessID,
        offeringId,
        customer,
        offering: argOffering,
    }: {
        businessID: string;
        offeringId: string;
        customer: ReadCustomerResponseData;
        offering?: Offering;
    }): Promise<string | void> {
        let offering = argOffering;
        if (!offering) {
            const { offering: contractOffering } = await this.contractService.findOne({
                businessID,
                customerId: customer?.customerId,
                offeringId,
                offeringEnrollmentDate: customer?.offeringEnrollmentDate,
            });
            offering = contractOffering;
        }
        if (!offering || offering.billingCycle !== ValidBillingCycles.topUp) {
            OfferingTopUpChecker.logger.warn(
                `Offering: ${offeringId} is not a top up offering, skipping customer: ${customer?.customerId}`,
            );
            return;
        }
        return (offering as UsageBased).processTopUp({ customer, creditService: this.creditService });
    }
}

