import { CustomerService } from '../../customer/customer.service.js';
import { paymentChannel } from '../../customer/dto/create-customer.dto.js';
import { ReadCustomerUsageData } from '../../customer/dto/read-customer.dto.js';
import { ReadCustomerResponseData } from '../../customer/entities/customer.entity.js';
import { CreditService } from '../../credit/credit.service.js';
import { countBasedUnits, roundingEnum } from '../../dimensions/dto/create-dimension.dto.js';
import { InvoicesService } from '../../invoice/invoices.service.js';
import { SchedulerService } from '../../scheduler/scheduler.service.js';
import { SchedulerStatus, SupportedMeasurementFrequencies, schedulerType } from '../../scheduler/dto/scheduler.dto.js';
import { FreeDimensionOnInvoice } from '../../setting/dto/FreeDimensionOnInvoice.js';
import { ReadSettingsResponseData } from '../../setting/dto/read-setting.dto.js';
import { ValidBillingCycles } from '../dto/createOffering.dto.js';
import { ReadOfferingResponseData } from '../dto/readOffering.dto.js';
import { SupportedCurrencies } from '../dto/SupportedCurrencies.js';
import { Offering, UsageBased } from './offeringPackage.entity.js';
import { OfferingType } from './OfferingType.js';

jest.mock('../../analytics/analytics.service', () => ({
    AnalyticsService: {
        getExchangeRate: jest.fn(() => 1),
    },
}));

describe('Top up offerings', () => {
    const fakeBusinessID = 'fakeBusinessID';
    const fakeCustomerID = 'fakeCustomerID';
    const fakeOfferingId = 'fakeOfferingId';
    const fakeSubject = 'fakeSubject';
    const fakeSettings = { freeDimensionOnInvoice: FreeDimensionOnInvoice.show } as ReadSettingsResponseData;
    const dimensionId = 'fakeDimensionId';
    let invoicesService: InvoicesService;
    let customerService: CustomerService;
    let schedulerService: SchedulerService;
    let creditService: CreditService;
    let topUpOffering: ReadOfferingResponseData;
    let customer: ReadCustomerResponseData;

    const buildOffering = (offeringConfig?: Partial<ReadOfferingResponseData>): UsageBased =>
        Offering.getInstance(
            { ...topUpOffering, ...offeringConfig },
            fakeCustomerID,
            fakeBusinessID,
            invoicesService,
            fakeSettings,
            schedulerService,
            customerService,
            undefined,
            undefined,
            creditService,
        ) as UsageBased;

    const mockUsage = (value: string) =>
        jest.spyOn(customerService, 'findUsageForCustomer').mockImplementation(
            async () =>
                ({
                    message: 'fake',
                    data: [
                        {
                            dimensionId,
                            usage: [
                                {
                                    startTime: new Date().toISOString(),
                                    endTime: new Date().toISOString(),
                                    value,
                                },
                            ],
                        },
                    ],
                }) as ReadCustomerUsageData,
        );

    beforeAll(() => {
        //eslint-disable-next-line
        //@ts-ignore
        invoicesService = new InvoicesService();
        //eslint-disable-next-line
        //@ts-ignore
        customerService = new CustomerService();
        //eslint-disable-next-line
        //@ts-ignore
        schedulerService = new SchedulerService();
        //eslint-disable-next-line
        //@ts-ignore
        creditService = new CreditService();
    });

    beforeEach(() => {
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(invoicesService, 'create').mockImplementation(async () => ({
            invoiceId: 'fakeInvoiceId',
            message: 'fake',
        }));
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(customerService, 'findUsageForCustomer').mockImplementation(async () => ({ message: 'fake' }));
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(creditService, 'create').mockImplementation(async () => ({}));
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(schedulerService, 'create').mockImplementation(async () => ({}));
        topUpOffering = {
            offeringId: fakeOfferingId,
            offeringName: 'Top Up Plan',
            offeringType: OfferingType.usageBased,
            currency: SupportedCurrencies.USD,
            billingCycle: ValidBillingCycles.topUp,
            topUpAmount: '100',
            dimensions: [
                {
                    dimensionId,
                    dimensionName: 'fake',
                    usageIncrement: '1',
                    consumptionPrice: '1',
                    consumptionUnit: { type: 'count', unit: countBasedUnits['count-based'] },
                    rounding: roundingEnum.ceiling,
                },
            ],
        };
        customer = {
            customerId: fakeCustomerID,
            customerName: 'fakeCustomerName',
            paymentChannel: paymentChannel.manual,
            businessID: fakeBusinessID,
            currency: SupportedCurrencies.USD,
            email: 'fakeEmail',
            creditBalance: '100',
        } as ReadCustomerResponseData;
    });

    afterEach(() => {
        jest.clearAllMocks();
    });

    afterAll(() => {
        jest.resetAllMocks();
    });

    test('Top up offerings default the top up threshold to 0.2', () => {
        expect(buildOffering().topUpThreshold).toEqual('0.2');
        expect(buildOffering({ topUpThreshold: '0.5' }).topUpThreshold).toEqual('0.5');
    });

    test('Top up offerings are scheduled hourly on the offering level', async () => {
        const offeringInstance = buildOffering();
        await offeringInstance.enroll(fakeSubject, customer);
        expect(schedulerService.create).toBeCalledTimes(1);
        expect(schedulerService.create).toBeCalledWith({
            schedulerID: fakeOfferingId,
            schedulerType: schedulerType.billing,
            schedulerStatus: SchedulerStatus.live,
            scheduleParameters: { businessID: fakeBusinessID, offeringId: fakeOfferingId },
            rate: SupportedMeasurementFrequencies.everyHour,
            subject: fakeSubject,
            businessID: fakeBusinessID,
        });
    });

    test('A balance which is exactly at the threshold is not topped up', async () => {
        const offeringInstance = buildOffering();
        await offeringInstance.topUp({ customer: { ...customer, creditBalance: '20' } });
        expect(invoicesService.create).toBeCalledTimes(0);
    });

    test('A balance which is below the threshold is topped up to the top up amount', async () => {
        const offeringInstance = buildOffering();
        await offeringInstance.topUp({ customer: { ...customer, creditBalance: '19.99' } });
        expect(invoicesService.create).toBeCalledTimes(1);
        expect(invoicesService.create).toBeCalledWith(
            expect.objectContaining({
                businessID: fakeBusinessID,
                customerId: fakeCustomerID,
                storePaymentAsCredit: true,
            }),
        );
        //eslint-disable-next-line
        //@ts-ignore
        const { items } = invoicesService.create.mock.calls[0][0];
        expect(items.getLineItems()).toEqual([
            { name: 'Top Up Plan - Top Up', quantity: 1, unitCost: 80.01, description: undefined },
        ]);
    });

    test('Enrollment tops up the customer wallet when the balance is below the threshold', async () => {
        const offeringInstance = buildOffering();
        await offeringInstance.enroll(fakeSubject, { ...customer, creditBalance: '0' });
        expect(invoicesService.create).toBeCalledTimes(1);
        //eslint-disable-next-line
        //@ts-ignore
        const { items } = invoicesService.create.mock.calls[0][0];
        expect(items.getLineItems()[0].unitCost).toEqual(100);
    });

    test('Hourly usage is deducted from the wallet and does not create a usage invoice', async () => {
        mockUsage('30');
        const offeringInstance = buildOffering();
        await offeringInstance.processBilling(undefined, undefined, customer);
        expect(creditService.create).toBeCalledTimes(1);
        expect(creditService.create).toBeCalledWith({
            businessID: fakeBusinessID,
            customerId: fakeCustomerID,
            timestamp: expect.anything(),
            transactionAmount: '-30.00',
            metadata: expect.objectContaining({ offeringId: fakeOfferingId, reason: expect.anything() }),
        });
        // The remaining balance of 70 is above the threshold of 20, therefore no top up occurs
        expect(invoicesService.create).toBeCalledTimes(0);
    });

    test('Hourly usage which exceeds the balance is deducted in full and tops the wallet back up', async () => {
        mockUsage('130');
        const offeringInstance = buildOffering();
        await offeringInstance.processBilling(undefined, undefined, customer);
        expect(creditService.create).toBeCalledTimes(1);
        expect(creditService.create).toBeCalledWith(
            expect.objectContaining({
                transactionAmount: '-130.00',
            }),
        );
        expect(invoicesService.create).toBeCalledTimes(1);
        //eslint-disable-next-line
        //@ts-ignore
        const { items, storePaymentAsCredit } = invoicesService.create.mock.calls[0][0];
        expect(storePaymentAsCredit).toEqual(true);
        // The balance after the usage deduction is -30, therefore the top up charges 130
        expect(items.getLineItems()[0].unitCost).toEqual(130);
        expect(customer.creditBalance).toEqual('-30');
    });

    test('Zero usage does not create a credit transaction but still evaluates the top up', async () => {
        const offeringInstance = buildOffering();
        await offeringInstance.processBilling(undefined, undefined, { ...customer, creditBalance: '10' });
        expect(creditService.create).toBeCalledTimes(0);
        expect(invoicesService.create).toBeCalledTimes(1);
        //eslint-disable-next-line
