s=open(p).read()
old="""    public async getCurrentCreditBalance(customer?: ReadCustomerResponseData): Promise<number> {
        if (customer?.creditBalance !== undefined && customer?.creditBalance !== null) {
            return parseFloat(customer.creditBalance as unknown as string);
        }"""
new="""    public async getCurrentCreditBalance(customer?: ReadCustomerResponseData): Promise<number> {
        const customerBalance = parseFloat(customer?.creditBalance as unknown as string);
        if (!isNaN(customerBalance)) {
            return customerBalance;
        }"""
assert s.count(old)==1
s=s.replace(old,new,1)
open(p,'w').write(s)
PYEOF
npx eslint "src/**/*.ts" --quiet && npm run build 2>&1 | tail -3 && timeout 900 npx jest --config ./jest.unit.config.json --forceExit --runInBand src/offering src/microservices 2>&1 | grep -E "Tests:|✕"
